import{_ as s,C as o,o as n,c as l,ag as t,E as a}from"./chunks/framework.CtWPcAmt.js";const f=JSON.parse('{"title":"Multi-Vendor Marketplace","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/introduction.md","filePath":"getting-started/introduction.md","lastUpdated":1786121967000}'),i={name:"getting-started/introduction.md"};function g(c,e,d,m,u,p){const r=o("ImagePopup");return n(),l("div",null,[e[0]||(e[0]=t('<h1 id="multi-vendor-marketplace" tabindex="-1">Multi-Vendor Marketplace <a class="header-anchor" href="#multi-vendor-marketplace" aria-label="Permalink to &quot;Multi-Vendor Marketplace&quot;">​</a></h1><p>The <a href="https://bagisto.com/en/laravel-multi-vendor-marketplace/" target="_blank" rel="noreferrer">Multi-Vendor Marketplace</a> turns a standard Bagisto store into a full marketplace. The admin keeps control of the platform — sellers, commissions, product approvals, moderation and payouts — while each seller gets a dedicated <strong>Seller Panel</strong> to run their own store, and customers shop across many sellers from a single cart.</p><div class="info custom-block"><p class="custom-block-title">What&#39;s in this section</p><p>This section walks through every part of the marketplace, grouped by who uses it: the <strong>marketplace admin</strong>, the <strong>sellers</strong>, and the <strong>customers</strong>. Each capability below links to its own page.</p></div>',3)),a(r,{src:"/images/introduction/admin-marketplace.png",alt:"Marketplace section in the admin panel"}),e[1]||(e[1]=t('<h2 id="for-the-marketplace-admin" tabindex="-1">For the marketplace admin <a class="header-anchor" href="#for-the-marketplace-admin" aria-label="Permalink to &quot;For the marketplace admin&quot;">​</a></h2><p>The admin panel gains a <strong>Marketplace</strong> section that governs the whole platform:</p><ul><li><strong><a href="/sellers/seller-management">Seller Management</a></strong> — review, approve, edit, suspend and log in as sellers, and watch each seller&#39;s <strong>account health</strong> and flags.</li><li><strong>Product approval &amp; assignment</strong> — an <strong><a href="/catalog/product-management#drafts-submission-and-approval">approval queue</a></strong> for seller products, and <strong><a href="/catalog/selling-existing-products">Selling Existing Products</a></strong> so sellers can list existing catalog items as their own (and the admin can assign products to sellers).</li><li><strong><a href="/payments/commission-management">Commissions</a></strong> and <strong><a href="/payments/mass-payout-management">Mass Payout</a></strong> — set commission rates and settle many sellers at once, alongside per-seller <strong><a href="/payments/payment-management">Payments</a></strong>.</li><li><strong><a href="/subscriptions/seller-subscription-management">Subscription Plans</a></strong> — paid plans that cap product counts, staff counts, allowed product types and permissions.</li><li><strong>Moderation</strong> — <strong><a href="/moderation/seller-product-flagging">Seller &amp; Product Flagging</a></strong> with configurable flag reasons, plus account-health scoring that surfaces problem sellers automatically.</li><li><strong>Marketing</strong> — publish <strong><a href="/marketing/product-discounts">Product Discounts</a></strong> for sellers to join, and run marketplace-wide <strong><a href="/marketing/checkout-deals">Checkout Deals</a></strong>.</li><li><strong><a href="/orders/fulfilment-carriers">Fulfilment Carriers</a></strong> — connect one courier account for the whole marketplace so sellers can buy shipping labels, schedule pickups and track shipments without seeing the credentials.</li><li><strong><a href="/sellers/featured-sellers">Featured Sellers</a></strong> — highlight top sellers on the storefront, ranked by orders, products or ratings.</li><li><strong><a href="/sellers/seller-attributes">Seller Attributes</a></strong> and the <strong>seller product form</strong> — define custom registration/profile fields and choose which fields appear on the seller product form.</li></ul><h2 id="for-sellers" tabindex="-1">For sellers <a class="header-anchor" href="#for-sellers" aria-label="Permalink to &quot;For sellers&quot;">​</a></h2><p>Each seller signs in to their <strong>Seller Panel</strong> — a dedicated dashboard with a grouped sidebar (Catalog, Inventories, Pricing, Marketing, Sales, Performance, Reporting, Communication, Customers, Plans, Settings) and full dark-mode support:</p><ul><li><strong>Catalog</strong> — <strong><a href="/catalog/product-management">Product Management</a></strong>, <strong><a href="/catalog/selling-existing-products">Selling Existing Products</a></strong>, <strong><a href="/catalog/product-barcode">Product Barcode</a></strong> and <strong><a href="/catalog/bulk-upload">Bulk Upload</a></strong>. Sellers can save <strong><a href="/catalog/draft-products">draft products</a></strong>, and use <strong><a href="/catalog/magic-ai">Magic AI</a></strong> to generate product content within admin-set limits.</li><li><strong>Inventories &amp; Pricing</strong> — dedicated <strong>Manage Inventory</strong> and <strong>Manage Pricing</strong> screens, plus <strong><a href="/inventory/inventory-source-management">Inventory Sources</a></strong> for multiple stock locations.</li><li><strong>Sales</strong> — <strong><a href="/orders/order-management">Orders</a></strong>, <strong><a href="/orders/booking-management">Bookings</a></strong> and <strong><a href="/orders/return-merchandise-authorization">Returns (RMA)</a></strong>.</li><li><strong>Marketing</strong> — sellers create their own <strong><a href="/marketing/product-discounts">Product Discounts</a></strong> and <strong><a href="/marketing/checkout-deals">Checkout Deals</a></strong>, and can join the admin&#39;s product discounts.</li><li><strong>Performance &amp; Reporting</strong> — an <strong>account-health</strong> score on the Performance menu, and <strong><a href="/reporting/seller-reporting">sales, product and customer reports</a></strong>.</li><li><strong>Team, customers &amp; messaging</strong> — <strong><a href="/sellers/seller-user-role-management">Users &amp; Roles</a></strong>, <strong><a href="/customers/customer-management">Customer insights</a></strong>, and <strong><a href="/customers/communications">Communication</a></strong> with the admin and buyers.</li></ul><h2 id="for-customers" tabindex="-1">For customers <a class="header-anchor" href="#for-customers" aria-label="Permalink to &quot;For customers&quot;">​</a></h2><ul><li>A public store page per seller, with the seller&#39;s products, banner, ratings and contact.</li></ul>',8)),a(r,{src:"/images/introduction/seller-storefront.png",alt:"A seller's storefront"}),e[2]||(e[2]=t('<ul><li><strong>Product offers</strong> — compare the different sellers carrying the same product before buying.</li><li><strong><a href="/moderation/rating-management">Ratings &amp; reviews</a></strong> for both products and sellers.</li><li><strong><a href="/moderation/seller-product-flagging">Flagging</a></strong> to report an inappropriate seller or product.</li><li>Direct <strong><a href="/customers/communications">messaging</a></strong> with sellers from the account area.</li><li><strong>One cart</strong> spanning products from several sellers and the admin.</li></ul><div class="tip custom-block"><p class="custom-block-title">New here?</p><p>Start with <strong><a href="/sellers/seller-management">Seller Management</a></strong> to see how a seller joins and how the admin manages them end to end.</p></div>',2))])}const k=s(i,[["render",g]]);export{f as __pageData,k as default};
